 S.workouts=S.workouts.filter(w=>w&&typeof w==='object').map(w=>({...w,ex:Array.isArray(w.ex)?w.ex.filter(x=>x&&typeof x==='object').map(x=>({...x,n:safeName(x.n),sets:Array.isArray(x.sets)?x.sets.filter(z=>z&&typeof z==='object'):[]})).filter(x=>x.n):[]}));
 if(S.cur)S.cur.ex=S.cur.ex.filter(x=>x&&typeof x==='object').map(x=>({...x,n:safeName(x.n)})).filter(x=>x.n);
