calc:async()=>{if(!gr)return toast('Open the rank form first');const k=gr.u=='lb'?1/2.20462:1,n=String(gr.n||'').trim(),was=!!S.rk[n],f=gr.f=='F'?1:0,t=R.t[R.alias[n]||n]?.[f],w=num(gr.w)*k,r0=num(gr.r),r=Math.round(r0),b=num(gr.b)*k,h=num(gr.h);if(!EX[n]||!t)return toast('Choose a supported exercise from the list');if(!Number.isInteger(r0)||r<1||r>12)return toast('Reps must be a whole number from 1 to 12');if(b<=0)return toast('Enter your bodyweight');if(w<0||(w<=0&&EX[n].t!='W'))return toast('Enter the weight you lifted');if(h&&(!Number.isFinite(h)||h<120||h>230))return toast('Height must be between 120 and 230 cm');const baseH=h||num(S.set.heightCm)||175,hf=heightFactor(baseH),W=EX[n].t=='W'?w+b:w,e=r==1?W:W*(1+r/30),rawX=e/b,x=rankScore(n,e,b,baseH),af=ageFactor(S.set.age),adj=t.map(v=>v*af);let i=0;adj.forEach((v,j)=>{if(x>=v)i=j});const nx=adj[i+1],span=nx===undefined?1:Math.max(.0001,nx-adj[i]),pc=i===MAX_RANK?100:Math.max(0,Math.min(100,(x-adj[i])/span*100)),rec={n,w,r,b,u:gr.u,f:gr.f,i,x,e,pc,need:i===MAX_RANK?null:Math.max(0,(nx*rankDifficulty(n)/hf)*b-e),d:iso(),age:S.set.age??null,h:h||num(S.set.heightCm)||null,rawX};S.rk[n]={...rec,auto:false};gr.res=S.rk[n];if(!bw())S.bw.push({d:iso(),kg:b});refreshRanks(true);await save();render();sheet();toast('Rank '+(was?'updated':'saved')+' · ranks refreshed')},
